// Same cadence maths as RE-05, on the email channel.
// Days between last_touch and now, compared against the interval for the lead's grade.
const cfg = $('Config').first().json;
const CADENCE = {
  HOT: Number(cfg.CADENCE_HOT_DAYS),
  WARM: Number(cfg.CADENCE_WARM_DAYS),
  COLD: Number(cfg.CADENCE_COLD_DAYS),
  JUNK: 999
};
const MAX_FOLLOWUPS = Number(cfg.MAX_FOLLOWUPS);
const HOLD_HOURS = Number(cfg.CONVERSATION_HOLD_HOURS);
const CAP = Number(cfg.DAILY_SEND_CAP);
const TZ = cfg.TIMEZONE || 'Asia/Kolkata';
const STOPPED = ['Booked', 'Lost', 'Dropped'];
const now = Date.now();
const ms = (v) => new Date(v || 0).getTime() || 0;
const istDay = (v) => v ? new Date(v).toLocaleDateString('en-CA', { timeZone: TZ }) : '';
const today = new Date().toLocaleDateString('en-CA', { timeZone: TZ });

const due = [];
const skipped = { stopped: 0, in_conversation: 0, capped: 0, not_due: 0, no_email: 0, junk: 0, already_today: 0 };

for (const l of $input.all().map(i => i.json)) {
  const status = String(l.status || 'New').trim();

  // 1. Finished leads are never touched again.
  if (STOPPED.includes(status)) { skipped.stopped++; continue; }

  // 2. Never talk over a live conversation. RE-00 sets Engaged the moment a buyer replies.
  //    Once they have been quiet for HOLD_HOURS the conversation is over and nurture resumes -
  //    a permanent Engaged skip would drop everyone who ever replied out of nurture for good.
  if (status === 'Engaged') {
    const quietHours = (now - ms(l.last_inbound_at || l.last_touch)) / 3600000;
    if (quietHours < HOLD_HOURS) { skipped.in_conversation++; continue; }
  }

  // 3. Hard stop, counting AUTOMATED follow-ups only - not button taps.
  const sent = Number(l.followup_count || 0);
  if (sent >= MAX_FOLLOWUPS) { skipped.capped++; continue; }

  // 4. RE-05 sweeps WhatsApp an hour earlier and writes last_touch, so an already-messaged lead
  //    is normally no longer due by now. This is the belt-and-braces check for the case where
  //    RE-05 ran late, partially failed, or overlapped this run.
  if (istDay(l.last_followup_at) === today) { skipped.already_today++; continue; }

  // 5. Cadence by grade.
  const grade = String(l.grade || 'WARM').toUpperCase();
  if (grade === 'JUNK') { skipped.junk++; continue; }
  const interval = CADENCE[grade] ?? CADENCE.WARM;
  const days = (now - ms(l.last_touch || l.created_at)) / 86400000;
  if (days < interval) { skipped.not_due++; continue; }

  // 6. This is the email arm.
  const email = String(l.email || '').trim();
  if (!email || !email.includes('@')) { skipped.no_email++; continue; }

  due.push({
    ...l,
    email,
    grade,
    cadence_days: interval,
    days_since_touch: Math.floor(days),
    followup_number: sent + 1,
    max_followups: MAX_FOLLOWUPS,
    resumed_after_conversation: status === 'Engaged'
  });
}

// Longest-ignored first, so nobody starves if the daily cap bites.
due.sort((a, b) => b.days_since_touch - a.days_since_touch);
const send = due.slice(0, CAP);
skipped.over_daily_cap = due.length - send.length;
return send.map(l => ({ json: { ...l, sweep: { due: due.length, sending: send.length, skipped } } }));

// Never send a half-written email. If the model gave us nothing usable, skip this lead
// entirely rather than sending filler and burning one of its six touches.
const lead = $('Find Follow-Ups Due').all()[$itemIndex].json;
const blocks = Array.isArray($json.content) ? $json.content : [];
const text = blocks.filter(b => b.type === 'text').map(b => b.text).join('').trim();
let ai = null;
if ($json.stop_reason !== 'refusal' && text) { try { ai = JSON.parse(text); } catch (e) { ai = null; } }

const clean = (s) => String(s || '').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
const subject = clean(ai && ai.subject).slice(0, 120);
const html = String((ai && ai.email_html) || '').trim();
const usable = subject.length > 5 && html.length > 40;

return { json: {
  ...lead,
  subject,
  email_html: html,
  internal_note: clean(ai && ai.internal_note),
  usable
} };

const cfg = $('Config').first().json;
const TZ = cfg.TIMEZONE || 'Asia/Kolkata';
const SLA_MIN = Number(cfg.SLA_MINUTES || 15);
const MAX_FOLLOWUPS = Number(cfg.MAX_FOLLOWUPS);
const HOLD_HOURS = Number(cfg.CONVERSATION_HOLD_HOURS);
const all = $input.all().map(i => i.json);
const mins = (v) => (Date.now() - (new Date(v || 0).getTime() || Date.now())) / 60000;
const days = (v) => mins(v) / 1440;
const grade = (l) => String(l.grade || '').toUpperCase();
const CLOSED = ['Booked', 'Lost', 'Dropped'];
const live = all.filter(l => !CLOSED.includes(l.status));

const bySource = {};
for (const l of all) {
  const s = l.source || 'unknown';
  bySource[s] = bySource[s] || { total: 0, hot: 0, junk: 0, visits: 0, booked: 0 };
  bySource[s].total++;
  if (grade(l) === 'HOT') bySource[s].hot++;
  if (grade(l) === 'JUNK') bySource[s].junk++;
  if (l.status === 'Visit Scheduled') bySource[s].visits++;
  if (l.status === 'Booked') bySource[s].booked++;
}

return [{ json: {
  date: new Date().toLocaleDateString('en-IN', { timeZone: TZ, dateStyle: 'full' }),
  total: all.length,
  live: live.length,
  hot: live.filter(l => grade(l) === 'HOT').length,
  warm: live.filter(l => grade(l) === 'WARM').length,
  cold: live.filter(l => grade(l) === 'COLD').length,
  junk: all.filter(l => grade(l) === 'JUNK').length,
  unowned: live.filter(l => !l.owner).length,
  breached_sla: live.filter(l => l.status === 'New' && mins(l.created_at) > SLA_MIN).length,
  stale_7d: live.filter(l => days(l.last_touch) > 7).length,
  in_conversation: live.filter(l => l.status === 'Engaged' && (mins(l.last_inbound_at || l.last_touch) / 60) < HOLD_HOURS).length,
  nurturing: live.filter(l => l.status === 'Nurturing').length,
  at_cap: live.filter(l => Number(l.followup_count || 0) >= MAX_FOLLOWUPS).length,
  visits: all.filter(l => l.status === 'Visit Scheduled').length,
  booked: all.filter(l => l.status === 'Booked').length,
  sla_minutes: SLA_MIN,
  max_followups: MAX_FOLLOWUPS,
  source_table: Object.entries(bySource)
    .sort((a, b) => b[1].total - a[1].total)
    .map(([k, v]) => `<tr><td>${k}</td><td align="center">${v.total}</td><td align="center">${v.hot}</td><td align="center">${v.junk}</td><td align="center">${v.visits}</td><td align="center">${v.booked}</td><td align="center">${v.total ? Math.round(v.booked / v.total * 100) : 0}%</td></tr>`)
    .join('')
} }];
